     1	// Release checks for .github/workflows/jusprin_release.yml.
     2	//
     3	//   node release.mjs version <Version.hpp>
     4	//       Prints JusPrin's version, the one in Version.hpp.
     5	//   node release.mjs check <Version.hpp> <releases.json> <tags.txt>
     6	//       Reads GitHub's release list (drafts included, as an authenticated
     7	//       request returns it) and the repository's tags, one refs/tags/... per
     8	//       line. Fails if this version was already published, is not above
     9	//       every published JusPrin version, or its tag already exists. Prints
    10	//       key=value lines for $GITHUB_OUTPUT: version, tag, prerelease,
    11	//       draft_id.
    12	//   node release.mjs guide <Version.hpp> <checked-version.txt>
    13	//       Prints why the release must wait for the guide check, or nothing
    14	//       when docs/guide/checked-version.txt, which scripts/check_guide.py
    15	//       writes when a full run passes, names this version. The workflow
    16	//       decides what to do with it, since a box on its form can override it.
    17	//
    18	// The update check (ReleaseFeed.cpp) reads tags vX.Y.Z and jusprin/vX.Y.Z.
    19	// New releases are tagged jusprin/vX.Y.Z, as JusPrin 1.4.0 was: the
    20	// repository still holds OrcaSlicer's own tags v2.0.0 to v2.3.1, and
    21	// publishing a draft whose tag exists attaches it to that tag's commit.
    22	
    23	import { existsSync, readFileSync } from 'node:fs';
    24	import { pathToFileURL } from 'node:url';
    25	
    26	const SEMVER = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z.-]+)?$/;
    27	
    28	export function parseVersion(text) {
    29	    const match = SEMVER.exec(text);
    30	    if (!match)
    31	        return null;
    32	    return {
    33	        text,
    34	        core: [Number(match[1]), Number(match[2]), Number(match[3])],
    35	        prerelease: match[4] ? match[4].split('.') : [],
    36	    };
    37	}
    38	
    39	// Semantic Versioning 2.0.0 precedence: a version with a pre-release part
    40	// ranks below the same version without one.
    41	export function compareVersions(a, b) {
    42	    for (let i = 0; i < 3; ++i)
    43	        if (a.core[i] !== b.core[i])
    44	            return a.core[i] < b.core[i] ? -1 : 1;
    45	    if (a.prerelease.length === 0 || b.prerelease.length === 0)
    46	        return b.prerelease.length - a.prerelease.length;
    47	    for (let i = 0; i < Math.min(a.prerelease.length, b.prerelease.length); ++i) {
    48	        const x = a.prerelease[i], y = b.prerelease[i];
    49	        const xn = /^\d+$/.test(x), yn = /^\d+$/.test(y);
    50	        if (x === y)
    51	            continue;
    52	        if (xn && yn)
    53	            return Number(x) < Number(y) ? -1 : 1;
    54	        if (xn !== yn)
    55	            return xn ? -1 : 1;
    56	        return x < y ? -1 : 1;
    57	    }
    58	    return a.prerelease.length - b.prerelease.length;
    59	}
    60	
    61	export function tagVersion(tag) {
    62	    let version = tag.startsWith('jusprin/') ? tag.slice('jusprin/'.length) : tag;
    63	    if (version.startsWith('v'))
    64	        version = version.slice(1);
    65	    return parseVersion(version);
    66	}
    67	
    68	export function readVersion(header) {
    69	    const match = /kVersion\[\]\s*=\s*"([^"]*)"/.exec(header);
    70	    if (!match)
    71	        throw new Error('Version.hpp has no kVersion = "X.Y.Z" line');
    72	    const version = parseVersion(match[1]);
    73	    if (!version)
    74	        throw new Error(`Version.hpp's version "${match[1]}" is not X.Y.Z or X.Y.Z-label`);
    75	    return version;
    76	}
    77	
    78	export function checkRelease(version, releases, tags = []) {
    79	    const tag = `jusprin/v${version.text}`;
    80	    // A draft has no tag until it is published, so an existing one belongs to
    81	    // something else.
    82	    if (tags.includes(`refs/tags/${tag}`))
    83	        throw new Error(`The tag ${tag} already exists. JusPrin ${version.text} would be published on its commit.`);
    84	    let draftId = '';
    85	    for (const release of releases) {
    86	        const released = tagVersion(release.tag_name ?? '');
    87	        if (!released || compareVersions(released, version) !== 0)
    88	            continue;
    89	        if (!release.draft)
    90	            throw new Error(`JusPrin ${version.text} is already released (${release.tag_name}). Raise the version in Version.hpp.`);
    91	        if (release.tag_name === tag) {
    92	            if (draftId)
    93	                throw new Error(`There are two drafts tagged ${tag}. Delete one.`);
    94	            draftId = String(release.id);
    95	        }
    96	    }
    97	    for (const release of releases) {
    98	        if (release.draft)
    99	            continue;
   100	        const released = tagVersion(release.tag_name ?? '');
   101	        if (released && compareVersions(released, version) > 0)
   102	            throw new Error(`JusPrin ${version.text} is below the released ${released.text} (${release.tag_name}).`);
   103	    }
   104	    return { version: version.text, tag, prerelease: version.prerelease.length > 0, draftId };
   105	}
   106	
   107	// The record says the check passed for this version on some commit, not on
   108	// the one being released: committing the record makes a new commit.
   109	export function guideCheckProblem(version, record) {
   110	    const checked = (record ?? '').trim();
   111	    const todo = 'Run scripts/check_guide.py --ask-ai on a built copy of this commit and commit what it changes, '
   112	               + 'as docs/guide/README.md describes under "Before a release".';
   113	    if (!checked)
   114	        return `The guide has never been checked: docs/guide/checked-version.txt is missing. ${todo}`;
   115	    if (checked !== version.text)
   116	        return `The guide was last checked for JusPrin ${checked}, not ${version.text} (docs/guide/checked-version.txt). ${todo}`;
   117	    return '';
   118	}
   119	
   120	function main(argv) {
   121	    const [command, headerPath, releasesPath, tagsPath] = argv;
   122	    const version = readVersion(readFileSync(headerPath, 'utf8'));
   123	    if (command === 'version') {
   124	        console.log(version.text);
   125	        return;
   126	    }
   127	    if (command === 'check') {
   128	        const releases = JSON.parse(readFileSync(releasesPath, 'utf8')).flat();
   129	        if (!tagsPath)
   130	            throw new Error('check needs the tag list too');
   131	        const tags = readFileSync(tagsPath, 'utf8').split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
   132	        const result = checkRelease(version, releases, tags);
   133	        console.log(`version=${result.version}`);
   134	        console.log(`tag=${result.tag}`);
   135	        console.log(`prerelease=${result.prerelease}`);
   136	        console.log(`draft_id=${result.draftId}`);
   137	        return;
   138	    }
   139	    if (command === 'guide') {
   140	        const recordPath = argv[2];
   141	        const problem = guideCheckProblem(version, existsSync(recordPath) ? readFileSync(recordPath, 'utf8') : null);
   142	        if (problem)
   143	            console.log(problem);
   144	        return;
   145	    }
   146	    throw new Error(`unknown command "${command}"`);
   147	}
   148	
   149	if (import.meta.url === pathToFileURL(process.argv[1]).href) {
   150	    try {
   151	        main(process.argv.slice(2));
   152	    } catch (error) {
   153	        console.error(`::error::${error.message}`);
   154	        process.exit(1);
   155	    }
   156	}
#pragma once

#include "libslic3r_version.h"

#include <string>

namespace Slic3r::GUI::JusPrin::Updates {

// JusPrin's own version: what Preferences shows and what the update check
// compares with the version in each JusPrin release tag. It is separate
// from SoftFever_VERSION, OrcaSlicer's version, which this build keeps
// because 3MF projects, profile updates, the user_backup-v<version> folder
// and AppConfig's upgrade logic all read it.
inline constexpr char kVersion[] = "2.0.0";

// The version a problem report or a saved chat names: JusPrin's and the
// OrcaSlicer release it is built on, as "JusPrin 2.0.0 (OrcaSlicer 2.5.0)".
// Not SLIC3R_VERSION, which is OrcaSlicer's Bambu network-plugin
// compatibility number (02.08.01.55), not a release anyone can look up.
inline std::string version_label() { return std::string("JusPrin ") + kVersion + " (OrcaSlicer " + SoftFever_VERSION + ")"; }

// The User-Agent of every request JusPrin sends to its own server, so the
// server can tell JusPrin releases apart. Orca's Http sends
// "JusPrin/<SoftFever_VERSION>" by default, which names the OrcaSlicer
// release and is the same for every JusPrin release built on it.
inline std::string user_agent() { return std::string("JusPrin/") + kVersion + " OrcaSlicer/" + SoftFever_VERSION; }

} // namespace Slic3r::GUI::JusPrin::Updates

